import{_ as s,o,c as t,ah as r}from"./chunks/framework.D4KxWb5R.js";const m=JSON.parse('{"title":"Le bureau","description":"","frontmatter":{},"headers":[],"relativePath":"guide/desk.md","filePath":"src/guide/desk.md"}'),a={name:"guide/desk.md"};function i(n,e,u,c,l,d){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="le-bureau" tabindex="-1">Le bureau <a class="header-anchor" href="#le-bureau" aria-label="Permalink to &quot;Le bureau&quot;">​</a></h1><p>L&#39;intranet est ouvert à tout compte actif. Le menu de gauche réunit, sous <strong>Intranet</strong>, votre bureau, les communications et les ressources ; sous <strong>Administration</strong>, les fonctions de votre poste (absentes si votre poste n&#39;en a pas). <strong>Voir le site</strong> ouvre le site public.</p><p>Tout ce que vous voyez est filtré par votre <a href="./introduction.html#notions-a-connaitre">périmètre</a>.</p><h2 id="mon-bureau" tabindex="-1">Mon bureau <a class="header-anchor" href="#mon-bureau" aria-label="Permalink to &quot;Mon bureau&quot;">​</a></h2><p>La page d&#39;accueil de l&#39;intranet affiche :</p><ul><li><strong>Mon périmètre</strong> : vos produits, zones et bureaux (« Tous les produits et toutes les zones » pour la direction) ;</li><li><strong>Dernières communications</strong> et <strong>Ressources récentes</strong> ;</li><li><strong>Espaces produits</strong> : un accès à chaque produit de votre périmètre ;</li><li>des bandeaux d&#39;alerte selon votre poste : nouveaux messages de contact à traiter, produits désynchronisés.</li></ul><p>Si aucun poste ne vous est encore attribué, le bureau vous l&#39;indique : demandez à l&#39;administrateur général de compléter votre compte.</p><h2 id="communications" tabindex="-1">Communications <a class="header-anchor" href="#communications" aria-label="Permalink to &quot;Communications&quot;">​</a></h2><p><strong>Communications</strong> liste les annonces qui vous concernent : celles adressées à tout M&#39;City, et celles ciblées sur votre poste, votre département, un produit, une zone ou un bureau de votre périmètre, ou sur vous nommément. Chaque communication indique son auteur, sa date et sa cible.</p><p>Une communication est rédigée dans une seule langue, choisie par son auteur.</p><h2 id="ressources" tabindex="-1">Ressources <a class="header-anchor" href="#ressources" aria-label="Permalink to &quot;Ressources&quot;">​</a></h2><p><strong>Ressources</strong> réunit les documents, procédures, notes, contacts et liens partagés. Filtrez par type ; ouvrez un lien ou téléchargez un document.</p><ul><li>Une ressource <strong>générale</strong> est visible de tous les comptes.</li><li>Une ressource rattachée à un produit n&#39;est visible que si votre périmètre couvre ce produit ; elle apparaît aussi dans l&#39;espace du produit.</li></ul><h2 id="espaces-produits" tabindex="-1">Espaces produits <a class="header-anchor" href="#espaces-produits" aria-label="Permalink to &quot;Espaces produits&quot;">​</a></h2><p>Chaque produit actif de votre périmètre a son espace. Vous y trouvez :</p><ul><li>les zones où le produit est présent ;</li><li>les équipes responsables et leurs membres ;</li><li>les communications et les ressources propres au produit ;</li><li><strong>Voir la page publique</strong> : sa landing page sur le site ;</li><li><strong>Ouvrir le back-office</strong> : son back-office, sans ressaisir vos identifiants.</li></ul><p>Le bouton <strong>Ouvrir le back-office</strong> n&#39;apparaît que si l&#39;accès vous est accordé, compte par compte ou parce que vous êtes membre d&#39;une équipe responsable du produit. Sinon, l&#39;espace vous l&#39;indique ; faites la demande à l&#39;administrateur général. Être dans le périmètre d&#39;un produit ne suffit pas pour ouvrir son back-office.</p><h2 id="acceder-a-un-back-office-produit" tabindex="-1">Accéder à un back-office produit <a class="header-anchor" href="#acceder-a-un-back-office-produit" aria-label="Permalink to &quot;Accéder à un back-office produit&quot;">​</a></h2><ol><li>Ouvrez l&#39;espace du produit, puis <strong>Ouvrir le back-office</strong>.</li><li>Le back-office vous connecte avec votre compte M&#39;City (bouton « Se connecter avec M&#39;City » sur sa page de connexion, si vous y arrivez directement).</li><li>Si vous n&#39;êtes pas encore connecté à M&#39;City, la connexion M&#39;City (et sa double authentification) vous est demandée d&#39;abord.</li></ol><p>Se déconnecter de M&#39;City ferme aussi les sessions des back-offices ouverts depuis cette session. Ce que vous pouvez faire dans un back-office dépend de votre poste : pour Auticway, voir <a href="./auticway.html">Back-office Auticway</a>.</p>',20)])])}const f=s(a,[["render",i]]);export{m as __pageData,f as default};
